ground_truth_sql:
SELECT r.tingkat_kesulitan, AVG(r.waktu_masak) AS rata_waktu
FROM resep AS r
GROUP BY r.tingkat_kesulitan;

SELECT m.status_aktif, COUNT(*) AS total_masakan
FROM masakan AS m
GROUP BY m.status_aktif;

SELECT judul_resep, waktu_masak
FROM resep
WHERE waktu_masak > (
  SELECT AVG(waktu_masak) FROM resep
);

SELECT kode_masakan, nama_masakan, level_pedas
FROM masakan
WHERE level_pedas > (
  SELECT AVG(level_pedas) FROM masakan
);

SELECT b.nama_bahan
FROM bahan AS b
WHERE b.id_bahan NOT IN (
  SELECT DISTINCT rb.id_bahan
  FROM resep_bahan AS rb
);

SELECT judul_resep, waktu_masak
FROM resep
WHERE waktu_masak = (SELECT MAX(waktu_masak) FROM resep);

SELECT kode_masakan, nama_masakan, level_pedas
FROM masakan
WHERE level_pedas = (SELECT MAX(level_pedas) FROM masakan);
